# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Route partition-sized traffic with capacitated minimum-cost flow.

    Each destination requires one unit for every partition.  Edge throughput is
    conservatively converted to an integral number of such units, then
    ``network_simplex`` chooses the lowest traffic-weighted-cost flow.  The
    resulting flow is decomposed into valid directed paths, allowing different
    partitions to use different networks when a cheap route is scarce.
    """
    import math

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dst for dst in dsts if dst != src))
    if not terminals:
        for dst in dsts:
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, [])
        return topology

    # A unit of flow is one partition transfer.  floor is deliberately
    # conservative: a route advertised as 2.8 units never carries 3 paths.
    flow_graph = nx.DiGraph()
    flow_graph.add_nodes_from(G.nodes)
    for u, v, data in G.edges(data=True):
        try:
            cost = float(data["cost"])
            capacity = int(math.floor(float(data.get("throughput", 0))))
        except (KeyError, TypeError, ValueError):
            continue
        if u != v and math.isfinite(cost) and capacity > 0:
            # Integer weights avoid numerical ambiguity in network_simplex.
            flow_graph.add_edge(
                u, v, capacity=capacity, weight=int(round(cost * 1000000))
            )

    demand = {node: 0 for node in flow_graph}
    required = len(terminals) * num_partitions
    demand[src] = -required
    for dst in terminals:
        demand[dst] += num_partitions
    nx.set_node_attributes(flow_graph, demand, "demand")

    def shortest_paths_fallback():
        """Return independent least-cost paths if capacity data is infeasible."""
        result = {}
        for dst in terminals:
            path = nx.shortest_path(G, src, dst, weight="cost")
            result[dst] = [
                [[u, v, G[u][v]] for u, v in zip(path, path[1:])]
                for _ in range(num_partitions)
            ]
        return result

    try:
        _, flow = nx.network_simplex(flow_graph)
        residual = nx.DiGraph()
        for u, outgoing in flow.items():
            for v, amount in outgoing.items():
                if amount > 0:
                    residual.add_edge(u, v, remaining=int(amount))

        routed = {}
        for dst in terminals:
            routed[dst] = []
            for _ in range(num_partitions):
                available = nx.DiGraph(
                    (u, v) for u, v, data in residual.edges(data=True)
                    if data["remaining"] > 0
                )
                path = nx.shortest_path(available, src, dst)
                edges = []
                for u, v in zip(path, path[1:]):
                    residual[u][v]["remaining"] -= 1
                    edges.append([u, v, G[u][v]])
                routed[dst].append(edges)
    except Exception:
        routed = shortest_paths_fallback()

    for dst in dsts:
        if dst == src:
            paths = [[] for _ in range(num_partitions)]
        else:
            paths = routed[dst]
        for partition, edges in enumerate(paths):
            topology.set_dst_partition_paths(dst, partition, edges)
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


